76	function JobMetadataSection({ jobId }: { jobId: string }) {
77	  const [open, setOpen] = useState(false);
78	  const [location, setLocation] = useState("");
79	  const [department, setDepartment] = useState("");
80	  const [employmentType, setEmploymentType] = useState("Full-time");
81	  const [expiresAt, setExpiresAt] = useState("");
82	  const [isFeatured, setIsFeatured] = useState(false);
83	  const [saving, setSaving] = useState(false);
84	  // loaded tracks whether DB data has been fetched — blocks form render until then
85	  // to prevent user input being silently overwritten by the async load.
86	  const [loaded, setLoaded] = useState(false);
87	
88	  useEffect(() => {
89	    // Reset loaded state when job changes so we don't show stale data
90	    setLoaded(false);
91	    setLocation("");
92	    setDepartment("");
93	    setEmploymentType("Full-time");
94	    setExpiresAt("");
95	    setIsFeatured(false);
96	
97	    let cancelled = false;
98	    (async () => {
99	      const { data } = await (supabase as any)
100	        .from("jobs")
101	        .select("location, department, employment_type, expires_at, is_featured")
102	        .eq("id", jobId)
103	        .single();
104	      if (!cancelled) {
105	        setLocation(data?.location ?? "");
106	        setDepartment(data?.department ?? "");
107	        setEmploymentType(data?.employment_type ?? "Full-time");
108	        setExpiresAt(data?.expires_at ? new Date(data.expires_at).toISOString().split("T")[0] : "");
109	        setIsFeatured(data?.is_featured ?? false);
110	        setLoaded(true);
111	      }
112	    })();
113	    return () => { cancelled = true; };
114	  }, [jobId]);
115	
116	  const handleSave = async () => {
117	    setSaving(true);
118	    try {
119	      const { error } = await (supabase as any)
120	        .from("jobs")
121	        .update({
122	          location: location.trim() || null,
123	          department: department.trim() || null,
124	          employment_type: employmentType,
125	          expires_at: expiresAt ? new Date(expiresAt).toISOString() : null,
126	          is_featured: isFeatured,
127	        })
128	        .eq("id", jobId);
129	      if (error) throw error;
130	      toast.success("Job details saved");
131	    } catch {
132	      toast.error("Failed to save job details");
133	    } finally {
134	      setSaving(false);
135	    }
136	  };
137	
138	  return (
139	    <Collapsible open={open} onOpenChange={setOpen} className="mt-3">
140	      <CollapsibleTrigger className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors w-full">
141	        <ChevronDown className={`h-3 w-3 transition-transform ${open ? "" : "-rotate-90"}`} />
142	        <MapPin className="h-3 w-3" />
143	        Job Details (for career page)
144	      </CollapsibleTrigger>
145	      <CollapsibleContent className="mt-3">
146	        <div className="rounded-lg border border-border bg-muted/20 p-3 space-y-3">
147	          {!loaded ? (
148	            <div className="grid grid-cols-2 gap-3">
149	              {[1, 2, 3, 4, 5, 6].map((i) => (
150	                <div key={i} className="space-y-1">
151	                  <Skeleton className="h-3 w-20" />
152	                  <Skeleton className="h-8 w-full" />
153	                </div>
154	              ))}
155	            </div>
156	          ) : (
157	          <div className="grid grid-cols-2 gap-3">
158	            <div className="space-y-1">
159	              <Label className="text-xs">Location</Label>
160	              <Input
161	                value={location}
162	                onChange={(e) => setLocation(e.target.value)}
163	                placeholder="e.g. San Francisco, CA"
164	                className="h-8 text-xs"
165	              />
166	            </div>
167	            <div className="space-y-1">
168	              <Label className="text-xs">Department</Label>
169	              <Input
170	                value={department}
171	                onChange={(e) => setDepartment(e.target.value)}
172	                placeholder="e.g. Engineering"
173	                className="h-8 text-xs"
174	              />
175	            </div>
176	            <div className="space-y-1">
177	              <Label className="text-xs">Employment Type</Label>
178	              <Select value={employmentType} onValueChange={setEmploymentType}>
179	                <SelectTrigger className="h-8 text-xs">
180	                  <SelectValue />
181	                </SelectTrigger>
182	                <SelectContent>
183	                  <SelectItem value="Full-time">Full-time</SelectItem>
184	                  <SelectItem value="Part-time">Part-time</SelectItem>
185	                  <SelectItem value="Contract">Contract</SelectItem>
186	                  <SelectItem value="Internship">Internship</SelectItem>
187	                  <SelectItem value="Freelance">Freelance</SelectItem>
188	                </SelectContent>
189	              </Select>
190	            </div>
191	            <div className="space-y-1">
192	              <Label className="text-xs">Expires at (optional)</Label>
193	              <Input
194	                type="date"
195	                value={expiresAt}
196	                onChange={(e) => setExpiresAt(e.target.value)}
197	                className="h-8 text-xs"
198	                min={new Date().toISOString().split("T")[0]}
199	              />
200	            </div>

200	            </div>
201	            <div className="space-y-1 flex flex-col justify-end">
202	              <div className="flex items-center justify-between rounded-md border border-border bg-background px-3 h-8">
203	                <Label className="text-xs cursor-pointer" htmlFor={`featured-${jobId}`}>
204	                  Featured
205	                </Label>
206	                <Switch
207	                  id={`featured-${jobId}`}
208	                  checked={isFeatured}
209	                  onCheckedChange={setIsFeatured}
210	                  aria-label="Mark job as featured"
211	                />
212	              </div>
213	            </div>
214	          </div>
215	          )}
216	          <Button
217	            size="sm"
218	            className="h-7 text-xs gap-1"
219	            onClick={handleSave}
220	            disabled={saving || !loaded}
221	          >
222	            {saving ? <Loader2 className="h-3 w-3 animate-spin" /> : <CheckCircle2 className="h-3 w-3" />}
223	            Save Details
224	          </Button>
225	        </div>
226	      </CollapsibleContent>
227	    </Collapsible>
228	  );
229	}
