233	interface JobDetailViewProps {
234	  selectedJobId: string | null;
235	  selectedJob: PastJob | null;
236	  results: Result[];
237	  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
238	  existingResumes: ExistingResume[];
239	  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
240	  onJobCreated: (job: PastJob) => void;
241	  onAuthRequired: () => void;
242	  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
243	  isAuthenticated?: boolean;
244	  pastJobs?: PastJob[];
245	  onBack?: () => void;
246	}
247	
248	interface UploadedFile {
249	  file: File;
250	  name: string;
251	}
252	
253	const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
254	
255	const JobDetailView = ({
256	  selectedJobId,
257	  selectedJob,
258	  results,
259	  setResults,
260	  existingResumes,
261	  setExistingResumes,
262	  onJobCreated,
263	  onAuthRequired,
264	  onJobUpdated,
265	  isAuthenticated = true,
266	  pastJobs = [],
267	  onBack,
268	}: JobDetailViewProps) => {
269	  const { user, profile, refreshProfile } = useAuth();
270	  const { data: config } = usePlatformConfig();
271	  const { team, members: teamMembers } = useTeam();
272	  const { stagesWithRejected: customPipelineStages } = usePipelineStages(team?.id);
273	  const { tagsForResume, addTag, removeTag } = useCandidateTags(selectedJobId);
274	
275	  const [jobTitle, setJobTitle] = useState("");
276	  const [jobDescription, setJobDescription] = useState("");
277	  const [files, setFiles] = useState<UploadedFile[]>([]);
278	  const [selectedFileIndexes, setSelectedFileIndexes] = useState<Set<number>>(new Set());
279	  const [ranking, setRanking] = useState(false);
280	  const [rankingProgress, setRankingProgress] = useState(0);
281	  const [scoredCount, setScoredCount] = useState(0);
282	  const [totalToScore, setTotalToScore] = useState(0);
283	  const [selectedCandidateId, setSelectedCandidateId] = useState<string | null>(null);
284	  const [dragOver, setDragOver] = useState(false);
285	  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
286	  const [validationErrors, setValidationErrors] = useState<string[]>([]);
287	  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
288	  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
289	  const [deleting, setDeleting] = useState(false);
290	  const [analyzingJd, setAnalyzingJd] = useState(false);
291	  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
292	  const [showArchived, setShowArchived] = useState(false);
293	  const [stageFilter, setStageFilter] = useState<string | null>(null);
294	  const [sourceFilter, setSourceFilter] = useState<string | null>(null);
295	  const [uploadSource, setUploadSource] = useState<string>("upload");
296	  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
297	  const [jdGeneratorOpen, setJdGeneratorOpen] = useState(false);
298	  const [csvImportOpen, setCsvImportOpen] = useState(false);
299	  const [stuckJobDetected, setStuckJobDetected] = useState(false);
300	  const [retrying, setRetrying] = useState(false);
301	  const [editingJd, setEditingJd] = useState(false);
302	  const [editedJdText, setEditedJdText] = useState("");
303	  const [confirmEditJdOpen, setConfirmEditJdOpen] = useState(false);
304	  const [activeTab, setActiveTab] = useState<"resumes" | "applications" | "pipeline" | "distribute">("resumes");
305	  const [showBulkUpload, setShowBulkUpload] = useState(false);
306	  const [showGuestLink, setShowGuestLink] = useState(false);
307	  const [blindMode, setBlindMode] = useState(false);
308	  // ── Email Sequences ───────────────────────────────────────────────────────
309	  const [enrollDialogOpen, setEnrollDialogOpen] = useState(false);
310	  const [rediscoveryOpen, setRediscoveryOpen] = useState(false);
311	  const [rediscoveryDismissed, setRediscoveryDismissed] = useState(false);
312	
313	  const queryClient = useQueryClient();
314	
315	  // Application count for badge on Applications tab
316	  const { data: applicationCount } = useQuery<number>({
317	    queryKey: ["applications-count", selectedJobId],
318	    queryFn: async () => {
319	      if (!selectedJobId) return 0;
320	      const { count, error } = await (supabase as any)
321	        .from("applications")
322	        .select("id", { count: "exact", head: true })
323	        .eq("job_id", selectedJobId);
324	      if (error) return 0;
325	      return count ?? 0;
326	    },
327	    enabled: !!selectedJobId && !!isAuthenticated,
328	    staleTime: 30_000,
329	  });
330	
331	  // Realtime subscription — refresh application count when new applications arrive
332	  useEffect(() => {
333	    if (!selectedJobId || !isAuthenticated) return;
334	
335	    const channel = supabase
336	      .channel(`app-count-${selectedJobId}`)
337	      .on(
338	        "postgres_changes",
339	        {
340	          event: "INSERT",
341	          schema: "public",
342	          table: "applications",
343	          filter: `job_id=eq.${selectedJobId}`,
344	        },
345	        () => {
346	          queryClient.invalidateQueries({ queryKey: ["applications-count", selectedJobId] });
347	        }
348	      )
349	      .subscribe();
350	
351	    return () => {
352	      supabase.removeChannel(channel);
353	    };
354	  }, [selectedJobId, isAuthenticated, queryClient]);
355	
356	  const resultsRef = useRef<HTMLDivElement>(null);
357	  const rankingFilesRef = useRef<Set<string>>(new Set());
358	  const rankingLockRef = useRef(false);
359	  const activeJobRef = useRef<string | null>(selectedJobId);
360	  const maxResumes = config?.max_resumes_per_job ?? 1000;
361	  const maxFileSizeMb = config?.max_file_size_mb ?? 5;
362	
363	  const isNewJobMode = selectedJobId === null;
364	  const isExistingJob = selectedJobId !== null && selectedJob !== null;
365	
366	  // Detect duplicate candidates across results (by name/email)
367	  const duplicateResumeIds = useMemo(() => findDuplicateResumeIds(results), [results]);
368	
369	  // Hiring Stage Tracker
370	  const { data: stages } = useStages(selectedJobId);
371	  const updateStageMutation = useUpdateStage();
372	  const stageSummary = useStageSummary(selectedJobId);
373	  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));
374	
375	  const handleStageChange = (resumeId: string, newStage: HiringStage) => {
376	    if (!selectedJobId) return;
377	    const current = stageMap.get(resumeId);
378	    updateStageMutation.mutate({
379	      resumeId,
380	      jobId: selectedJobId,
381	      newStage,
382	      currentStage: current?.stage,
383	    });
384	  };
385	
386	  const handleBulkUploadComplete = async () => {
387	    if (!selectedJobId) return;
388	    const { data: allResumes } = await supabase
389	      .from("resumes")
390	      .select("id, filename, file_path, candidate_name, created_at")
391	      .eq("job_id", selectedJobId)
392	      .order("created_at", { ascending: false });
393	    if (allResumes) setExistingResumes(allResumes);
394	    setShowBulkUpload(false);
395	  };
396	
397	  const formatCandidateName = (filename: string) => {
398	    const name = filename.replace(/\.\w+$/, "");
399	    if (UUID_REGEX.test(name)) return `Resume ${name.slice(0, 6).toUpperCase()}`;
400	    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
401	  };
402	
403	  // Merge unranked resumes
404	  const resultResumeIds = new Set(results.map((r) => r.resume_id));
405	  const pendingResumes: Result[] = existingResumes
406	    .filter((r) => !resultResumeIds.has(r.id))
407	    .map((r) => ({
408	      id: `pending-${r.id}`,
409	      resume_id: r.id,
410	      overall_score: 0,
411	      missing_skills: [], summary: null, interview_questions: null,
412	      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
413	      pending: true,
414	    }));
415	  const allResults = [...results, ...pendingResumes];
416	
417	  // Selection helpers
418	  const toggleSelectResume = (resumeId: string) => {
419	    setSelectedResumes((prev) => {
420	      const next = new Set(prev);
421	      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
422	      return next;
423	    });
424	  };
425	  const toggleSelectAll = () => {
426	    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
427	    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
428	  };
429	
430	  // Delete logic
431	  const deleteResume = async (resumeId: string, filePath: string | null) => {
432	    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
433	    await supabase.from("results").delete().eq("resume_id", resumeId);
434	    await supabase.from("resumes").delete().eq("id", resumeId);
435	    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
436	    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
437	    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
438	  };
439	
440	  const handleDeleteConfirm = async () => {
441	    if (!deleteConfirm) return;
442	    setDeleting(true);
443	    try {
444	      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
445	        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
446	        toast.success("Resume deleted");
447	      } else if (deleteConfirm.type === "bulk") {
448	        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
449	        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
450	        toast.success(`${toDelete.length} resume(s) deleted`);
451	      }
452	    } catch { toast.error("Failed to delete"); }
453	    finally { setDeleting(false); setDeleteConfirm(null); }
454	  };
455	
456	  // File handling
457	  const ALLOWED_TYPES = new Set([
458	    "application/pdf",
459	    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
460	    "application/msword",
461	    "application/rtf", "text/rtf",
462	    "text/plain",
463	    "application/zip", "application/x-zip-compressed",
464	  ]);
465	  const ALLOWED_EXTS = new Set(["pdf", "docx", "doc", "rtf", "txt", "zip"]);
466	
467	  const handleFileDrop = useCallback(async (e: React.DragEvent) => {
468	    e.preventDefault(); setDragOver(false);
469	    const raw = Array.from(e.dataTransfer.files).filter(
470	      (f) => ALLOWED_TYPES.has(f.type) || ALLOWED_EXTS.has(f.name.split(".").pop()?.toLowerCase() ?? "")
471	    );
472	    // Extract ZIP files inline
473	    const extracted: File[] = [];
474	    for (const f of raw) {
475	      if (f.name.toLowerCase().endsWith(".zip")) {
476	        try {
477	          const JSZip = (await import("jszip")).default;
478	          const zip = await JSZip.loadAsync(f);
479	          let count = 0;
480	          for (const [path, entry] of Object.entries(zip.files)) {
481	            if (entry.dir || path.startsWith("__MACOSX")) continue;
482	            const ext = path.split(".").pop()?.toLowerCase();
483	            if (!ext || !["pdf", "docx", "doc", "rtf", "txt"].includes(ext)) continue;
484	            const blob = await entry.async("blob");
485	            const name = path.split("/").pop() || path;
486	            const mimeMap: Record<string, string> = { pdf: "application/pdf", docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document", doc: "application/msword", rtf: "application/rtf", txt: "text/plain" };
487	            extracted.push(new File([blob], name, { type: mimeMap[ext] || "application/octet-stream" }));
488	            count++;
489	          }
490	          if (count > 0) toast.success(`Extracted ${count} resumes from ${f.name}`);
491	        } catch { toast.error(`Failed to extract ${f.name}`); }
492	      } else {
493	        extracted.push(f);
494	      }
495	    }
496	    addFiles(extracted);
497	  }, [files, maxResumes, maxFileSizeMb]);
498	
499	  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {

500	    if (!e.target.files) return;
501	    const raw = Array.from(e.target.files);
502	    const extracted: File[] = [];
503	    for (const f of raw) {
504	      if (f.name.toLowerCase().endsWith(".zip")) {
505	        try {
506	          const JSZip = (await import("jszip")).default;
507	          const zip = await JSZip.loadAsync(f);
508	          let count = 0;
509	          for (const [path, entry] of Object.entries(zip.files)) {
510	            if (entry.dir || path.startsWith("__MACOSX")) continue;
511	            const ext = path.split(".").pop()?.toLowerCase();
512	            if (!ext || !["pdf", "docx", "doc", "rtf", "txt"].includes(ext)) continue;
