77	function ScoreRingMini({ score }: { score: number }) {
78	  const size = 56;
79	  const sw = 5;
80	  const r = (size - sw) / 2;
81	  const c = 2 * Math.PI * r;
82	  const v = Math.min(Math.max(score, 0), 100);
83	  const dash = (v / 100) * c;
84	  const color = v >= 70 ? "#22c55e" : v >= 40 ? "#f59e0b" : "#ef4444";
85	  return (
86	    <div
87	      className="relative inline-flex items-center justify-center shrink-0"
88	      style={{ width: size, height: size }}
89	    >
90	      <svg width={size} height={size} className="-rotate-90">
91	        <circle
92	          cx={size / 2}
93	          cy={size / 2}
94	          r={r}
95	          fill="none"
96	          stroke="currentColor"
97	          strokeWidth={sw}
98	          className="text-muted/30"
99	        />
100	        <circle
101	          cx={size / 2}
102	          cy={size / 2}
103	          r={r}
104	          fill="none"
105	          stroke={color}
106	          strokeWidth={sw}
107	          strokeDasharray={`${dash} ${c - dash}`}
108	          strokeLinecap="round"
109	        />
110	      </svg>
111	      <span
112	        className="absolute text-sm font-bold tabular-nums"
113	        style={{ color }}
114	      >
115	        {Math.round(v)}
116	      </span>
117	    </div>
118	  );
119	}
